import { CircleCheck, LoaderCircle, Mail } from "lucide-react";
import { type ReactNode, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export interface ForgotPasswordPageProps {
  onSubmit: (email: string) => Promise<void>;
  title?: string;
  description?: string;
  brand?: ReactNode;
  footer?: ReactNode;
}

/**
 * 忘记密码页：提交邮箱后进入「发送成功」终态（不暴露邮箱是否存在）。
 */
export function ForgotPasswordPage({
  onSubmit,
  title = "重置密码",
  description = "输入注册邮箱，我们会发送重置链接",
  brand,
  footer,
}: ForgotPasswordPageProps) {
  const [email, setEmail] = useState("");
  const [pending, setPending] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    setPending(true);
    try {
      await onSubmit(email);
      setSent(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : "发送失败，请重试");
    } finally {
      setPending(false);
    }
  }

  return (
    <main className="bg-background flex min-h-svh items-center justify-center p-6">
      <Card className="w-full max-w-sm">
        <CardHeader className="items-center text-center">
          {brand}
          <CardTitle className="text-[22px] font-semibold tracking-tight">{title}</CardTitle>
          {description ? <CardDescription>{description}</CardDescription> : null}
        </CardHeader>
        <CardContent>
          {sent ? (
            <div className="flex flex-col items-center gap-3 py-4 text-center">
              <span className="bg-status-info-bg text-status-info flex size-10 items-center justify-center rounded-full">
                <Mail className="size-5" />
              </span>
              <CircleCheck className="text-status-success size-5" />
              <p className="text-sm text-muted-foreground">
                如果该邮箱已注册，重置链接已发送至 <span className="text-foreground">{email}</span>
                。
              </p>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="flex flex-col gap-4">
              <div className="grid gap-2">
                <Label htmlFor="forgot-email">邮箱</Label>
                <Input
                  id="forgot-email"
                  type="email"
                  autoComplete="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>
              {error ? (
                <p role="alert" className="text-destructive text-sm">
                  {error}
                </p>
              ) : null}
              <Button type="submit" disabled={pending} className="w-full">
                {pending ? (
                  <LoaderCircle className="animate-spin" data-icon="inline-start" />
                ) : null}
                {pending ? "发送中…" : "发送重置链接"}
              </Button>
            </form>
          )}
        </CardContent>
        {footer ? <CardFooter className="justify-center text-sm">{footer}</CardFooter> : null}
      </Card>
    </main>
  );
}

import { cn } from "cn";
import { LoaderCircle } from "lucide-react";
import { type ReactNode, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";

export interface OtpPageProps {
  /** 校验码长度（分格数），默认 6 */
  length?: number;
  /** 全部填满时自动提交；也可点击按钮提交 */
  onSubmit: (code: string) => Promise<void>;
  title?: string;
  description?: string;
  brand?: ReactNode;
  footer?: ReactNode;
}

/**
 * 验证码 / MFA 页：N 位分格输入（自动进格、退格回跳、粘贴整段填充、填满自动提交）。
 */
export function OtpPage({
  length = 6,
  onSubmit,
  title = "输入验证码",
  description = "验证码已发送至你的邮箱或手机",
  brand,
  footer,
}: OtpPageProps) {
  const [digits, setDigits] = useState<string[]>(() => Array.from({ length }, () => ""));
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const inputsRef = useRef<Array<HTMLInputElement | null>>([]);

  const code = digits.join("");

  async function submit(value: string) {
    setError(null);
    setPending(true);
    try {
      await onSubmit(value);
    } catch (err) {
      setError(err instanceof Error ? err.message : "验证失败，请重试");
      setDigits(Array.from({ length }, () => ""));
      inputsRef.current[0]?.focus();
    } finally {
      setPending(false);
    }
  }

  function setDigit(index: number, raw: string) {
    const value = raw.replace(/\D/g, "");
    if (value === "") {
      return;
    }
    setDigits((prev) => {
      const next = [...prev];
      // 支持一次输入/粘贴多位：从当前格起依次填充
      for (let offset = 0; offset < value.length && index + offset < length; offset++) {
        next[index + offset] = value[offset] ?? "";
      }
      const filled = next.join("");
      if (filled.length === length && !next.includes("")) {
        queueMicrotask(() => {
          const target = inputsRef.current[Math.min(index + value.length, length - 1)];
          target?.blur();
          void submit(filled);
        });
      }
      return next;
    });
    const focusIndex = Math.min(index + value.length, length - 1);
    inputsRef.current[focusIndex]?.focus();
  }

  function handleKeyDown(index: number, event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Backspace") {
      event.preventDefault();
      setDigits((prev) => {
        const next = [...prev];
        if (next[index]) {
          next[index] = "";
        } else if (index > 0) {
          next[index - 1] = "";
          inputsRef.current[index - 1]?.focus();
        }
        return next;
      });
    }
    if (event.key === "ArrowLeft" && index > 0) {
      inputsRef.current[index - 1]?.focus();
    }
    if (event.key === "ArrowRight" && index < length - 1) {
      inputsRef.current[index + 1]?.focus();
    }
  }

  return (
    <main className="bg-background flex min-h-svh items-center justify-center p-6">
      <Card className="w-full max-w-sm">
        <CardHeader className="items-center text-center">
          {brand}
          <CardTitle className="text-[22px] font-semibold tracking-tight">{title}</CardTitle>
          {description ? <CardDescription>{description}</CardDescription> : null}
        </CardHeader>
        <CardContent>
          <form
            onSubmit={(e) => {
              e.preventDefault();
              if (code.length === length && !code.includes("")) {
                void submit(code);
              }
            }}
            className="flex flex-col items-center gap-4"
          >
            <fieldset className="flex gap-2" aria-label={`${length} 位验证码`}>
              {digits.map((digit, index) => (
                <Input
                  key={index}
                  ref={(el) => {
                    inputsRef.current[index] = el;
                  }}
                  inputMode="numeric"
                  autoComplete={index === 0 ? "one-time-code" : "off"}
                  maxLength={length}
                  value={digit}
                  autoFocus={index === 0}
                  disabled={pending}
                  className={cn(
                    "size-11 text-center text-base font-medium tabular-nums",
                    error && "aria-invalid:border-destructive",
                  )}
                  onChange={(e) => setDigit(index, e.target.value)}
                  onKeyDown={(e) => handleKeyDown(index, e)}
                />
              ))}
            </fieldset>
            {error ? (
              <p role="alert" className="text-destructive text-sm">
                {error}
              </p>
            ) : null}
            <Button type="submit" className="w-full" disabled={pending || code.includes("")}>
              {pending ? <LoaderCircle className="animate-spin" data-icon="inline-start" /> : null}
              {pending ? "验证中…" : "验证"}
            </Button>
          </form>
        </CardContent>
        {footer ? <CardFooter className="justify-center text-sm">{footer}</CardFooter> : null}
      </Card>
    </main>
  );
}

import { LoaderCircle } from "lucide-react";
import { type ReactNode, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export interface SignInPageProps {
  onSubmit: (credentials: { email: string; password: string }) => Promise<void>;
  title?: string;
  description?: string;
  /** 品牌位（logo + 产品名），渲染在表单上方 */
  brand?: ReactNode;
  /** 表单下方区域（注册 / 忘记密码链接等） */
  footer?: ReactNode;
  submitLabel?: string;
}

/**
 * 登录页：品牌位 + 邮箱密码表单 + 错误展示。
 * onSubmit 抛错 → 表单内联展示（如 HttpError(401) 的「邮箱或密码错误」）；next 回跳由宿主处理。
 */
export function SignInPage({
  onSubmit,
  title = "欢迎回来",
  description = "登录你的账号以继续",
  brand,
  footer,
  submitLabel = "登录",
}: SignInPageProps) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    setPending(true);
    try {
      await onSubmit({ email, password });
    } catch (err) {
      setError(err instanceof Error ? err.message : "登录失败，请重试");
    } finally {
      setPending(false);
    }
  }

  return (
    <main className="bg-background flex min-h-svh items-center justify-center p-6">
      <Card className="w-full max-w-sm">
        <CardHeader className="items-center text-center">
          {brand}
          <CardTitle className="text-[22px] font-semibold tracking-tight">{title}</CardTitle>
          {description ? <CardDescription>{description}</CardDescription> : null}
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="flex flex-col gap-4">
            <div className="grid gap-2">
              <Label htmlFor="signin-email">邮箱</Label>
              <Input
                id="signin-email"
                type="email"
                autoComplete="email"
                required
                placeholder="you@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="signin-password">密码</Label>
              <Input
                id="signin-password"
                type="password"
                autoComplete="current-password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
            </div>
            {error ? (
              <p role="alert" className="text-destructive text-sm">
                {error}
              </p>
            ) : null}
            <Button type="submit" disabled={pending} className="w-full">
              {pending ? <LoaderCircle className="animate-spin" data-icon="inline-start" /> : null}
              {pending ? "登录中…" : submitLabel}
            </Button>
          </form>
        </CardContent>
        {footer ? <CardFooter className="justify-center text-sm">{footer}</CardFooter> : null}
      </Card>
    </main>
  );
}

import { CircleCheck, LoaderCircle } from "lucide-react";
import { type ReactNode, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export interface SignUpPageProps {
  onSubmit: (values: { name: string; email: string; password: string }) => Promise<void>;
  title?: string;
  description?: string;
  brand?: ReactNode;
  footer?: ReactNode;
}

/**
 * 注册页：姓名 + 邮箱 + 密码 + 确认密码（客户端一致性校验）。
 * 提交成功后由宿主切换 success 视图或直接登录。
 */
export function SignUpPage({
  onSubmit,
  title = "创建账号",
  description = "几秒钟完成注册",
  brand,
  footer,
}: SignUpPageProps) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const [done, setDone] = useState(false);

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    if (password !== confirm) {
      setError("两次输入的密码不一致");
      return;
    }
    setPending(true);
    try {
      await onSubmit({ name, email, password });
      setDone(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : "注册失败，请重试");
    } finally {
      setPending(false);
    }
  }

  return (
    <main className="bg-background flex min-h-svh items-center justify-center p-6">
      <Card className="w-full max-w-sm">
        <CardHeader className="items-center text-center">
          {brand}
          <CardTitle className="text-[22px] font-semibold tracking-tight">{title}</CardTitle>
          {description ? <CardDescription>{description}</CardDescription> : null}
        </CardHeader>
        <CardContent>
          {done ? (
            <div className="flex flex-col items-center gap-2 py-4 text-center">
              <CircleCheck className="text-status-success size-8" />
              <p className="text-sm text-muted-foreground">注册成功，请查收验证邮件完成激活。</p>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="flex flex-col gap-4">
              <div className="grid gap-2">
                <Label htmlFor="signup-name">姓名</Label>
                <Input
                  id="signup-name"
                  autoComplete="name"
                  required
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="signup-email">邮箱</Label>
                <Input
                  id="signup-email"
                  type="email"
                  autoComplete="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="signup-password">密码</Label>
                <Input
                  id="signup-password"
                  type="password"
                  autoComplete="new-password"
                  required
                  minLength={8}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="signup-confirm">确认密码</Label>
                <Input
                  id="signup-confirm"
                  type="password"
                  autoComplete="new-password"
                  required
                  value={confirm}
                  onChange={(e) => setConfirm(e.target.value)}
                />
              </div>
              {error ? (
                <p role="alert" className="text-destructive text-sm">
                  {error}
                </p>
              ) : null}
              <Button type="submit" disabled={pending} className="w-full">
                {pending ? (
                  <LoaderCircle className="animate-spin" data-icon="inline-start" />
                ) : null}
                {pending ? "提交中…" : "创建账号"}
              </Button>
            </form>
          )}
        </CardContent>
        {footer ? <CardFooter className="justify-center text-sm">{footer}</CardFooter> : null}
      </Card>
    </main>
  );
}

import { cn } from "cn";
import { Check, Minus } from "lucide-react";

export interface CellBooleanProps {
  value: boolean | undefined | null;
  /** 值文案（如 "启用/停用"）；缺省只渲染图标 */
  labels?: [string, string];
  className?: string;
}

/** 布尔单元格：true → 勾（success 令牌）；false/缺省 → 横线（muted），语义色不硬编码 */
export function CellBoolean({ value, labels, className }: CellBooleanProps) {
  const truthy = value === true;
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1.5 text-[13px]",
        truthy ? "text-status-success" : "text-muted-foreground",
        className,
      )}
      data-slot="cell-boolean"
    >
      {truthy ? (
        <Check className="size-3.5" aria-label={labels?.[0] ?? "是"} />
      ) : (
        <Minus className="size-3.5" aria-label={labels?.[1] ?? "否"} />
      )}
      {labels ? <span>{truthy ? labels[0] : labels[1]}</span> : null}
    </span>
  );
}

import { cn } from "cn";
import { Badge } from "@/components/ui/badge";

export interface EnumBadgeOption {
  value: string;
  label?: string;
  /** Badge variant（default/secondary/outline/ghost…），未配置用 secondary */
  variant?: "default" | "secondary" | "destructive" | "outline" | "ghost";
}

export interface CellEnumBadgeProps {
  value: string | undefined;
  options: EnumBadgeOption[];
  className?: string;
}

/** 枚举单元格：值 → Badge（选项表驱动 variant 与文案；未命中 outline 兜底） */
export function CellEnumBadge({ value, options, className }: CellEnumBadgeProps) {
  if (value === undefined || value === null || value === "") {
    return <span className={cn("text-muted-foreground text-[13px]", className)}>—</span>;
  }
  const option = options.find((o) => o.value === value);
  return (
    <Badge variant={option?.variant ?? "outline"} className={className} data-slot="cell-enum-badge">
      {option?.label ?? value}
    </Badge>
  );
}

import type { ComponentType, ReactNode } from "react";
import { CellBoolean } from "@/components/blocks/cells/cell-boolean/cell-boolean";
import {
  CellEnumBadge,
  type EnumBadgeOption,
} from "@/components/blocks/cells/cell-enum-badge/cell-enum-badge";
import { CellId } from "@/components/blocks/cells/cell-id/cell-id";
import {
  CellNumber,
  type CellNumberFormat,
} from "@/components/blocks/cells/cell-number/cell-number";
import { CellProgress } from "@/components/blocks/cells/cell-progress/cell-progress";
import { CellStatus } from "@/components/blocks/cells/cell-status/cell-status";
import { CellTags } from "@/components/blocks/cells/cell-tags/cell-tags";
import { CellTime } from "@/components/blocks/cells/cell-time/cell-time";
import { CellUser } from "@/components/blocks/cells/cell-user/cell-user";
import type { StatusBadgeTone } from "@/components/blocks/shared/status-badge/status-badge";

export type CellForType =
  | "id"
  | "time"
  | "status"
  | "user"
  | "boolean"
  | "number"
  | "enum-badge"
  | "tags"
  | "progress";

export interface CellForOptions {
  /** cell-status：值 → tone 映射 */
  map?: Record<string, StatusBadgeTone>;
  /** cell-status：活动态（呼吸点）值 */
  pulseFor?: string[];
  /** cell-number：格式 */
  format?: CellNumberFormat;
  unit?: string;
  /** cell-enum-badge：选项表 */
  options?: EnumBadgeOption[];
  /** cell-boolean：文案 */
  labels?: [string, string];
  /** cell-tags：最多展示数 */
  max?: number;
}

/** cellFor 产出的统一 cell 组件 props（value 来自列 accessor） */
export interface CellForValueProps {
  value: unknown;
}

/**
 * type → cell 组件映射器（L4 inferColumns / 手写列定义共用）。
 *
 * ```tsx
 * const TimeCell = cellFor("time");
 * const cols = [helper.accessor("createdAt", { cell: (info) => <TimeCell value={info.getValue()} /> })];
 * ```
 */
export function cellFor(
  type: CellForType,
  opts: CellForOptions = {},
): ComponentType<CellForValueProps> {
  const components: Record<CellForType, (p: { value: unknown }) => ReactNode> = {
    id: ({ value }) => <CellId value={typeof value === "string" ? value : String(value ?? "")} />,
    time: ({ value }) => <CellTime value={value as string | number | Date | undefined} />,
    status: ({ value }) => (
      <CellStatus value={value as string | undefined} map={opts.map} pulseFor={opts.pulseFor} />
    ),
    user: ({ value }) => <CellUser user={value as never} />,
    boolean: ({ value }) => (
      <CellBoolean value={value as boolean | undefined} labels={opts.labels} />
    ),
    number: ({ value }) => (
      <CellNumber value={value as number | undefined} format={opts.format} unit={opts.unit} />
    ),
    "enum-badge": ({ value }) => (
      <CellEnumBadge value={value as string | undefined} options={opts.options ?? []} />
    ),
    tags: ({ value }) => (
      <CellTags values={Array.isArray(value) ? (value as string[]) : undefined} max={opts.max} />
    ),
    progress: ({ value }) => <CellProgress value={value as never} />,
  };
  const render = components[type];
  function CellForValue({ value }: CellForValueProps) {
    return render({ value });
  }
  return CellForValue;
}

import { cn } from "cn";
import { Check, Copy } from "lucide-react";
import { useEffect, useState } from "react";

export interface CellIdProps {
  value: string | undefined;
  /** 显示位数（前缀截断展示，复制始终全量），默认 8 */
  chars?: number;
  className?: string;
}

/** ID 单元格：mono + 截断 + hover 复制（复制成功 2s 反馈） */
export function CellId({ value, chars = 8, className }: CellIdProps) {
  const [copied, setCopied] = useState(false);
  useEffect(() => {
    if (!copied) return;
    const timer = setTimeout(() => setCopied(false), 2000);
    return () => clearTimeout(timer);
  }, [copied]);

  if (value === undefined || value === null || value === "") {
    return <span className={cn("text-muted-foreground font-mono text-xs", className)}>—</span>;
  }

  const display = value.length > chars ? value.slice(0, chars) : value;
  return (
    <button
      type="button"
      title={`复制 ${value}`}
      onClick={() => {
        if (navigator?.clipboard) {
          void navigator.clipboard.writeText(value);
          setCopied(true);
        }
      }}
      className={cn(
        "group/cell-id inline-flex max-w-full items-center gap-1 rounded font-mono text-xs",
        "text-muted-foreground transition-colors hover:text-foreground",
        className,
      )}
      data-slot="cell-id"
    >
      <span className="truncate">{display}</span>
      {copied ? (
        <Check className="size-3 shrink-0 text-status-success" />
      ) : (
        <Copy className="size-3 shrink-0 opacity-0 transition-opacity group-hover/cell-id:opacity-100" />
      )}
    </button>
  );
}

import { cn } from "cn";

export type CellNumberFormat = "int" | "decimal" | "percent" | "bytes";

function formatValue(value: number, format: CellNumberFormat): string {
  switch (format) {
    case "int":
      return new Intl.NumberFormat(undefined, { maximumFractionDigits: 0 }).format(value);
    case "decimal":
      return new Intl.NumberFormat(undefined, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }).format(value);
    case "percent":
      return new Intl.NumberFormat(undefined, {
        style: "percent",
        minimumFractionDigits: 0,
        maximumFractionDigits: 1,
      }).format(value);
    case "bytes": {
      const units = ["B", "KB", "MB", "GB", "TB"];
      let v = value;
      let unit = 0;
      while (v >= 1024 && unit < units.length - 1) {
        v /= 1024;
        unit += 1;
      }
      return `${new Intl.NumberFormat(undefined, { maximumFractionDigits: 1 }).format(v)} ${units[unit]}`;
    }
  }
}

export interface CellNumberProps {
  value: number | undefined | null;
  format?: CellNumberFormat;
  /** 单位后缀（如 " 个" / "ms"） */
  unit?: string;
  className?: string;
}

/** 数值单元格：tabular-nums + Intl 格式化（int/decimal/percent/bytes） + 可选单位 */
export function CellNumber({ value, format = "int", unit, className }: CellNumberProps) {
  if (value === undefined || value === null || Number.isNaN(value)) {
    return (
      <span className={cn("text-muted-foreground tabular-nums text-[13px]", className)}>—</span>
    );
  }
  return (
    <span className={cn("tabular-nums text-[13px]", className)} data-slot="cell-number">
      {formatValue(value, format)}
      {unit ? <span className="text-muted-foreground ml-0.5 text-xs">{unit}</span> : null}
    </span>
  );
}

import { cn } from "cn";
import type { StatusBadgeTone } from "@/components/blocks/shared/status-badge/status-badge";

export interface CellProgressProps {
  /** 0-100 百分比；或 {current,total} 自动换算 */
  value: number | { current: number; total: number } | undefined;
  /** 状态色（progress 前景色走 --status-* 令牌；缺省用 primary） */
  state?: StatusBadgeTone;
  /** 是否显示百分比数字（默认 true） */
  showValue?: boolean;
  className?: string;
}

const stateFill: Record<StatusBadgeTone, string> = {
  success: "[&::-webkit-progress-value]:bg-status-success [&::-moz-progress-bar]:bg-status-success",
  warning: "[&::-webkit-progress-value]:bg-status-warning [&::-moz-progress-bar]:bg-status-warning",
  danger: "[&::-webkit-progress-value]:bg-status-danger [&::-moz-progress-bar]:bg-status-danger",
  info: "[&::-webkit-progress-value]:bg-status-info [&::-moz-progress-bar]:bg-status-info",
  neutral:
    "[&::-webkit-progress-value]:bg-muted-foreground [&::-moz-progress-bar]:bg-muted-foreground",
};

/** 进度单元格：语义 <progress>（状态色映射 --status-*）+ 百分比；支持 {current,total} 形态 */
export function CellProgress({ value, state, showValue = true, className }: CellProgressProps) {
  let percent: number | undefined;
  if (typeof value === "number") {
    percent = value;
  } else if (value && typeof value === "object") {
    percent = value.total > 0 ? Math.round((value.current / value.total) * 100) : 0;
  }
  if (percent === undefined || Number.isNaN(percent)) {
    return <span className={cn("text-muted-foreground text-[13px]", className)}>—</span>;
  }
  const clamped = Math.max(0, Math.min(100, percent));
  return (
    <span className={cn("inline-flex items-center gap-2", className)} data-slot="cell-progress">
      <progress
        value={clamped}
        max={100}
        aria-label={`${clamped}%`}
        className={cn(
          "bg-muted h-1.5 w-24 overflow-hidden rounded-full",
          "[&::-webkit-progress-bar]:bg-transparent [&::-webkit-progress-value]:rounded-full [&::-moz-progress-bar]:rounded-full",
          "[&::-webkit-progress-value]:bg-primary [&::-moz-progress-bar]:bg-primary",
          state ? stateFill[state] : undefined,
        )}
      />
      {showValue ? (
        <span className="text-muted-foreground tabular-nums text-xs">{clamped}%</span>
      ) : null}
    </span>
  );
}

import { cn } from "cn";
import type { StatusBadgeTone } from "@/components/blocks/shared/status-badge/status-badge";
import { StatusBadge } from "@/components/blocks/shared/status-badge/status-badge";

export interface CellStatusProps {
  value: string | undefined;
  /** 值 → tone 映射，如 { running: 'success', failed: 'danger' }；未命中回落 neutral */
  map?: Record<string, StatusBadgeTone>;
  /** 活动态（呼吸点），如 running */
