function ColumnsMenu<TData extends RowData>({ table }: { table: ListTable<TData> }) {
  const columns = table.getAllLeafColumns().filter((c) => c.getCanHide());
  const order = table.state.columnOrder;
  const move = (id: string, dir: -1 | 1): void => {
    const current = order.length > 0 ? [...order] : columns.map((c) => c.id);
    const idx = current.indexOf(id);
    const target = idx + dir;
    if (idx < 0 || target < 0 || target >= current.length) return;
    const next = [...current];
    const [moved] = next.splice(idx, 1);
    if (moved) {
      next.splice(target, 0, moved);
      table.setColumnOrder(next);
    }
  };
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button variant="outline" size="sm" />}>
        <ChevronsUpDown data-icon="inline-start" />列
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-52">
        <DropdownMenuLabel>显示列</DropdownMenuLabel>
        {columns.map((column) => (
          <div key={column.id} className="flex items-center">
            <DropdownMenuCheckboxItem
              className="flex-1"
              checked={column.getIsVisible()}
              onCheckedChange={column.getToggleVisibilityHandler()}
              closeOnClick={false}
            >
              {String(columnDefTitle(column.id))}
            </DropdownMenuCheckboxItem>
            <span className="flex items-center">
              <button
                type="button"
                aria-label="上移"
                className="text-muted-foreground hover:text-foreground px-1"
                onClick={(e) => {
                  e.preventDefault();
                  move(column.id, -1);
                }}
              >
                <ArrowUp className="size-3" />
              </button>
              <button
                type="button"
                aria-label="下移"
                className="text-muted-foreground hover:text-foreground px-1"
                onClick={(e) => {
                  e.preventDefault();
                  move(column.id, 1);
                }}
              >
                <ChevronDown className="size-3" />
              </button>
            </span>
          </div>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function columnDefTitle(id: string): string {
  return id.startsWith("__")
    ? id === "__select"
      ? "选择"
      : id === "__expand"
        ? "展开"
        : "操作"
    : id;
}

import { Download, LoaderCircle } from "lucide-react";
import { useState } from "react";
import { Button } from "@/components/ui/button";

export interface ExportColumn<T> {
  key: string;
  header: string;
  /** 自定义序列化（默认 String(value)，undefined → 空串） */
  format?: (row: T) => string | number | undefined;
}

export interface ExportButtonProps<T> {
  /** 以当前应用的过滤/排序状态全量取数（由页面用 client.list 逐页拉齐后返回） */
  fetch: () => Promise<T[]>;
  columns: ExportColumn<T>[];
  filename: string;
  label?: string;
  className?: string;
  onExported?: (count: number) => void;
  onError?: (error: unknown) => void;
}

function csvEscape(value: string): string {
  if (/[",\n\r]/.test(value)) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

export function toCsv<T>(rows: T[], columns: ExportColumn<T>[]): string {
  const header = columns.map((c) => csvEscape(c.header)).join(",");
  const body = rows
    .map((row) =>
      columns
        .map((c) => {
          const value = c.format ? c.format(row) : (row as Record<string, unknown>)[c.key];
          return csvEscape(value === undefined || value === null ? "" : String(value));
        })
        .join(","),
    )
    .join("\n");
  return `${header}\n${body}`;
}

/** CSV 导出：按当前应用状态全量取数 → CSV（BOM 头保证 Excel 中文不乱码）→ 触发下载 */
export function ExportButton<T>({
  fetch,
  columns,
  filename,
  label = "导出 CSV",
  className,
  onExported,
  onError,
}: ExportButtonProps<T>) {
  const [busy, setBusy] = useState(false);

  const run = async (): Promise<void> => {
    setBusy(true);
    try {
      const rows = await fetch();
      const csv = toCsv(rows, columns);
      const blob = new Blob([`\uFEFF${csv}`], { type: "text/csv;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = filename.endsWith(".csv") ? filename : `${filename}.csv`;
      anchor.click();
      URL.revokeObjectURL(url);
      onExported?.(rows.length);
    } catch (error) {
      onError?.(error);
    } finally {
      setBusy(false);
    }
  };

  return (
    <Button
      variant="outline"
      size="sm"
      className={className ?? undefined}
      disabled={busy}
      onClick={() => void run()}
      data-slot="export-button"
    >
      {busy ? (
        <LoaderCircle data-icon="inline-start" className="animate-spin" />
      ) : (
        <Download data-icon="inline-start" />
      )}
      {label}
    </Button>
  );
}

import type { FacetResult } from "@fleetly/ui-component-core/data";
import type { FilterDef, FilterLeaf, FilterTree } from "@fleetly/ui-component-core/filters";
import { isFilterLeaf } from "@fleetly/ui-component-core/filters";
import { cn } from "cn";
import { Checkbox } from "@/components/ui/checkbox";

export interface FacetSidebarList {
  state: { filters: FilterTree | undefined };
  applyFilters: (tree?: FilterTree) => void;
}

export interface FacetSidebarProps {
  facetData: FacetResult[] | undefined;
  list: FacetSidebarList;
  /** facet 字段 → 展示名（缺省用字段名） */
  defs?: FilterDef[];
  className?: string;
}

/** 当前字段的 in 叶子值集合（无则空） */
function inValues(tree: FilterTree | undefined, field: string): string[] {
  const leaf = collectLeaves(tree).find((l) => l.field === field && l.op === "in");
  return Array.isArray(leaf?.value) ? (leaf.value as string[]) : [];
}

function collectLeaves(tree: FilterTree | undefined): FilterLeaf[] {
  if (tree === undefined) return [];
  if (isFilterLeaf(tree)) return [tree];
  return tree.children.flatMap((c) => collectLeaves(c));
}

/** 写入字段的 in 叶子（替换既有 in/nin 同字段叶子） */
function withInLeaf(
  tree: FilterTree | undefined,
  leaf: FilterLeaf,
  field: string,
): FilterTree | undefined {
  const others = collectRemove(tree, field);
  if (leaf.value === undefined || (Array.isArray(leaf.value) && leaf.value.length === 0)) {
    return others;
  }
  if (others === undefined) return leaf;
  if (isFilterLeaf(others)) return { combinator: "and", children: [others, leaf] };
  return { combinator: others.combinator, children: [...others.children, leaf] };
}

function collectRemove(tree: FilterTree | undefined, field: string): FilterTree | undefined {
  if (tree === undefined) return undefined;
  if (isFilterLeaf(tree)) return tree.field === field ? undefined : tree;
  const children = tree.children
    .map((c) => collectRemove(c, field))
    .filter((c): c is FilterTree => c !== undefined);
  if (children.length === 0) return undefined;
  if (children.length === 1) return children[0];
  return { combinator: tree.combinator, children };
}

/** facet 侧栏：按字段分组多选 + 计数（勾选即写入 in 过滤） */
export function FacetSidebar({ facetData, list, defs, className }: FacetSidebarProps) {
  if (facetData === undefined || facetData.length === 0) {
    return (
      <div className={cn("w-52 shrink-0", className)} data-slot="facet-sidebar" aria-busy="true">
        <div className="text-muted-foreground px-1 text-xs">facet 加载中…</div>
      </div>
    );
  }
  return (
    <div className={cn("w-52 shrink-0 space-y-5", className)} data-slot="facet-sidebar">
      {facetData.map((facet) => {
        const selected = inValues(list.state.filters, facet.field);
        const label = defs?.find((d) => d.field === facet.field)?.label ?? facet.field;
        return (
          <div key={facet.field} className="space-y-1.5">
            <p className="text-muted-foreground px-1 text-xs font-medium tracking-wider uppercase">
              {label}
            </p>
            <div className="space-y-0.5">
              {facet.buckets.map((bucket) => {
                const checked = selected.includes(bucket.value);
                return (
                  <span
                    key={bucket.value}
                    className="hover:bg-muted/50 flex items-center gap-2 rounded-md px-1 py-1 text-[13px]"
                  >
                    <Checkbox
                      checked={checked}
                      onCheckedChange={() => {
                        const next = checked
                          ? selected.filter((v) => v !== bucket.value)
                          : [...selected, bucket.value];
                        list.applyFilters(
                          withInLeaf(
                            list.state.filters,
                            { field: facet.field, op: "in", value: next },
                            facet.field,
                          ),
                        );
                      }}
                    />
                    <span className="min-w-0 flex-1 truncate">{bucket.value}</span>
                    <span className="text-muted-foreground tabular-nums text-xs">
                      {bucket.count}
                    </span>
                  </span>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
}

